result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so a token where `exp === now` passes through instead of being rejected. The fix is `<=`.

**Deeper issue:** `jwt.verify()` already validates expiry and throws `TokenExpiredError` — the manual check is redundant and duplicates logic incorrectly. The `catch` block also swallows all errors with the same generic message, hiding useful distinctions.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // jwt.verify already rejects expired tokens (including exp === now),
    // so no manual exp check is needed.
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    // Unexpected error (e.g. missing JWT_SECRET) — don't leak internals
    console.error('Auth middleware error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Before | After |
|---|---|---|
| Off-by-one on expiry | `exp < now` (allows `exp === now`) | Removed — `jwt.verify` uses `<=` internally |
| Error granularity | Single catch-all message | Separate handling for `TokenExpiredError`, `JsonWebTokenError`, `NotBeforeError` |
| Unexpected errors | Silently returns 401 | Logged + returns 500 to avoid leaking internals |
